import {NextResponse} from "next/server";import {getUserFromSession} from "@/lib/auth/session";import {getSupabaseAdmin} from "@/lib/supabase/server";import {DEFAULT_PROGRAM_KEY} from "@/lib/registration/types";import {enforceRegistrationCheckoutRateLimit,rateLimitResponseHeaders} from "@/lib/rate-limit";
export const dynamic="force-dynamic";
async function context(userId:string){const db=getSupabaseAdmin();const {data:group}=await db.from("registration_groups").select("id,registrations(id,is_primary_registrant,first_name,last_name,relationship_to_primary,guardian_registration_id,registration_product_id)").eq("owner_user_id",userId).eq("program_key",DEFAULT_PROGRAM_KEY).maybeSingle();const [blocks,request,settings]=await Promise.all([db.from("housing_blocks").select("id,name,minimum_nights,maximum_nights,earliest_arrival,latest_arrival,request_opens_at,request_closes_at,inventory_mode,capacity,reserved_count,occupancy_options,deposit_notice,eligibility_entitlement_id,housing_hotels(id,name,description,address_line_1,address_line_2,city,state,postal_code,website_url,map_url,photo_url)").eq("program_key",DEFAULT_PROGRAM_KEY).eq("active",true).order("display_order"),group?db.from("housing_requests").select("*,housing_hotels(name,address_line_1,city,state,postal_code,map_url,photo_url),housing_blocks(name,inventory_mode,minimum_nights),housing_request_registrants(registration_id)").eq("registration_group_id",group.id).order("created_at",{ascending:false}).limit(1).maybeSingle():Promise.resolve({data:null}),db.from("housing_settings").select("support_name,support_email,support_phone,attendee_disclaimer").eq("program_key",DEFAULT_PROGRAM_KEY).maybeSingle()]);let entitlementIds:string[]=[];if(group){const primary=(group.registrations as any[])?.find(r=>r.is_primary_registrant);if(primary?.registration_product_id){const {data}=await db.from("registration_product_entitlements").select("entitlement_id,access_entitlements!inner(entitlement_type,active)").eq("registration_product_id",primary.registration_product_id).eq("active",true).eq("access_entitlements.entitlement_type","housing").eq("access_entitlements.active",true);entitlementIds=(data??[]).map((x:any)=>x.entitlement_id)}}const eligibleBlocks=(blocks.data??[]).filter((b:any)=>entitlementIds.includes(b.eligibility_entitlement_id)).map((b:any)=>({...b,availabilityLabel:b.inventory_mode==="REQUEST_ONLY"?"Housing request available":b.reserved_count>=b.capacity?"Sold out":b.capacity-b.reserved_count<=5?"Limited":"Available"}));return {eligible:eligibleBlocks.length>0,blocks:eligibleBlocks,request:request.data??null,group:group??null,settings:settings.data??null};}
export async function GET(){const user=await getUserFromSession();if(!user?.id)return NextResponse.json({error:"Sign in required."},{status:401});return NextResponse.json(await context(user.id),{headers:{"Cache-Control":"private, no-store"}})}
export async function POST(request:Request){const user=await getUserFromSession();if(!user?.id)return NextResponse.json({error:"Sign in required."},{status:401});const rate=await enforceRegistrationCheckoutRateLimit(request,user.id);if(!rate.allowed)return NextResponse.json({error:"Too many housing requests."},{status:429,headers:rateLimitResponseHeaders(rate)});const b=await request.json().catch(()=>null),db=getSupabaseAdmin();const {data,error}=await db.rpc("submit_housing_request",{p_user_id:user.id,p_program_key:DEFAULT_PROGRAM_KEY,p_preference:String(b?.preference||""),p_block_id:b?.blockId||null,p_arrival:b?.arrival||null,p_departure:b?.departure||null,p_occupancy:b?.occupancy||null,p_registration_ids:Array.isArray(b?.registrationIds)?b.registrationIds:null});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({requestId:data,status:"submitted"},{status:201})}

