export async function POST(request:Request){const auth=await requireCheckInUser();if(!auth.ok)return NextResponse.json({error:auth.message},{status:auth.status});const rate=await enforceStaffScanRateLimit(request,auth.userId);if(!rate.allowed)return NextResponse.json({error:"Door scanner rate limit reached. Wait briefly and retry."},{status:429,headers:rateLimitResponseHeaders(rate)});const b=await request.json().catch(()=>null);if(b?.kind!=="scan")return NextResponse.json({error:"Unsupported action."},{status:400});try{const result:any=await processAccessScan({value:text(b.value,500),occurrenceId:text(b.occurrenceId,64),zoneId:text(b.zoneId,64),scannerUserId:auth.userId,inputMethod:b.inputMethod==="camera"?"camera":"manual",guardianPresent:b.guardianPresent===true});return NextResponse.json({...result,reasonLabel:SCAN_REASON_LABELS[result.reasonCode]||result.reasonCode},{headers:{"Cache-Control":"private, no-store"}})}catch{return NextResponse.json({decision:"VALIDATION_UNAVAILABLE",reasonCode:"VALIDATION_UNAVAILABLE",reasonLabel:"Server validation is unavailable. Do not admit; retry when connected.",entryRecorded:false},{status:503})}}
export async function PATCH(request:Request){const auth=await requireOwnerUser();if(!isOwnerAuthed(auth))return ownerAuthFailureResponse(auth);const b=await request.json().catch(()=>null),db=getSupabaseAdmin();if(b?.kind==="zone"){const {error}=await db.from("access_zones").upsert({program_key:DEFAULT_PROGRAM_KEY,zone_key:text(b.zoneKey,64).toUpperCase(),name:text(b.name),description:text(b.description)||null,active:b.active!==false,updated_by:auth.userId,created_by:auth.userId},{onConflict:"program_key,zone_key"});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({ok:true})}if(b?.kind==="rule"){const {error}=await db.from("occurrence_access_rules").upsert({event_occurrence_id:text(b.occurrenceId,64),access_zone_id:text(b.zoneId,64),entitlement_id:text(b.entitlementId,64)||null,access_mode:["TICKET","PROGRAM_CHECK_IN"].includes(b.accessMode)?b.accessMode:"REGISTRATION",usage_mode:b.usageMode==="SINGLE_ENTRY"?"SINGLE_ENTRY":"REENTRY_ALLOWED",allow_general_fallback:b.allowGeneralFallback===true,active:b.active!==false,updated_by:auth.userId,created_by:auth.userId},{onConflict:"event_occurrence_id,access_zone_id"});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({ok:true})}if(b?.kind==="staff"){const uid=text(b.userId,64);const {error}=await db.from("staff_permissions").upsert({user_id:uid,permission:"CHECK_IN",active:b.active!==false,assigned_by:auth.userId},{onConflict:"user_id,permission"});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({ok:true})}return NextResponse.json({error:"Unsupported action."},{status:400})}

