Id,updated_by:auth.userId}).select("*").single();return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({block:data},{status:201})}if(b?.kind==="settings"){const {error}=await db.from("housing_settings").upsert({program_key:DEFAULT_PROGRAM_KEY,support_name:text(b.supportName,160)||null,support_email:text(b.supportEmail,200)||null,support_phone:text(b.supportPhone,80)||null,attendee_disclaimer:text(b.attendeeDisclaimer)||null,updated_by:auth.userId},{onConflict:"program_key"});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({ok:true})}return NextResponse.json({error:"Unsupported action."},{status:400})}catch(e){return NextResponse.json({error:e instanceof Error?e.message:"Invalid housing configuration."},{status:400})}}
export async function PATCH(request:Request){const auth=await requireOwnerUser();if(!isOwnerAuthed(auth))return ownerAuthFailureResponse(auth);const b=await request.json().catch(()=>null),db=getSupabaseAdmin();if(b?.action==="status"){const {data,error}=await db.rpc("transition_housing_request",{p_request_id:text(b.requestId,64),p_status:text(b.status,20),p_actor_user_id:auth.userId,p_notes:text(b.notes)||null});return error||!data?NextResponse.json({error:error?.message||"Unable to update request."},{status:400}):NextResponse.json({ok:true})}const table=b?.kind==="hotel"?"housing_hotels":b?.kind==="block"?"housing_blocks":null;if(!table)return NextResponse.json({error:"Unsupported action."},{status:400});const {data,error}=await db.from(table).update({active:b.active===true,updated_by:auth.userId}).eq("id",text(b.id,64)).eq("program_key",DEFAULT_PROGRAM_KEY).select("id").maybeSingle();return error||!data?NextResponse.json({error:"Unable to update housing record."},{status:400}):NextResponse.json({ok:true})}

import { NextResponse } from "next/server";
import { requireOwnerUser } from "@/lib/owner/auth";
import { isOwnerAuthed, ownerAuthFailureResponse } from "@/lib/owner/api-response";
import { getSupabaseAdmin } from "@/lib/supabase/server";

export const dynamic = "force-dynamic";

export async function GET() {
  const auth = await requireOwnerUser();
  if (!isOwnerAuthed(auth)) return ownerAuthFailureResponse(auth);
  const { data, error } = await getSupabaseAdmin()
    .from("ticket_instances")
    .select("id,holder_name,status,complimentary,issued_at,used_at,ticket_products(name,event_occurrences(local_date,events(title)))")
    .order("created_at", { ascending: false })
    .limit(5000);
  if (error) return NextResponse.json({ error: "Unable to export ticket holders." }, { status: 500 });
  const escape = (value: unknown) => `"${String(value ?? "").replaceAll('"', '""')}"`;
  const rows = [
    ["Ticket ID", "Holder", "Product", "Event", "Event Date", "Status", "Complimentary", "Issued", "Used"],
    ...(data ?? []).map((ticket: any) => [ticket.id, ticket.holder_name, ticket.ticket_products?.name, ticket.ticket_products?.event_occurrences?.events?.title, ticket.ticket_products?.event_occurrences?.local_date, ticket.status, ticket.complimentary, ticket.issued_at, ticket.used_at]),
  ];
  return new NextResponse(rows.map((row) => row.map(escape).join(",")).join("\n"), { headers: { "Content-Type": "text/csv", "Content-Disposition": "attachment; filename=ticket-holders.csv", "Cache-Control": "private, no-store" } });
}

