export async function POST(request:Request){const auth=await requireOwnerUser();if(!isOwnerAuthed(auth))return ownerAuthFailureResponse(auth);const b=await request.json().catch(()=>null),db=getSupabaseAdmin();if(b?.kind==="ticket_product"){const occurrenceId=text(b.eventOccurrenceId,64);const {data:o}=await db.from("event_occurrences").select("id,events!inner(event_type,program_key)").eq("id",occurrenceId).eq("events.program_key",DEFAULT_PROGRAM_KEY).maybeSingle();if(!o)return NextResponse.json({error:"A real program event occurrence is required."},{status:400});const key=text(b.productKey,48).toUpperCase(),name=text(b.name,120),price=Number(b.priceCents),capacity=Number(b.capacity);if(!/^[A-Z][A-Z0-9_]{1,47}$/.test(key)||!name||!Number.isInteger(price)||price<0||!Number.isInteger(capacity)||capacity<0)return NextResponse.json({error:"Valid key, name, price, and capacity are required."},{status:400});const {data:ent,error:entError}=await db.from("access_entitlements").insert({program_key:DEFAULT_PROGRAM_KEY,entitlement_key:`MUSICAL_ENTRY_${key}`,name:`${name} Entry`,entitlement_type:"event_access",event_occurrence_id:occurrenceId,access_zone:"musical",single_use:true,usage_limit:1,active:true,created_by:auth.userId,updated_by:auth.userId}).select("id").single();if(entError)return NextResponse.json({error:entError.message},{status:400});const {data,error}=await db.from("ticket_products").insert({program_key:DEFAULT_PROGRAM_KEY,event_occurrence_id:occurrenceId,entitlement_id:ent.id,product_key:key,name,description:text(b.description)||null,price_cents:price,currency:"usd",capacity,sale_start:text(b.saleStart)||null,sale_end:text(b.saleEnd)||null,per_order_limit:Math.max(1,Number(b.perOrderLimit)||10),active:b.active===true,public:b.public===true,refundable:false,policy_reference:text(b.policyReference)||null,sort_order:Number(b.sortOrder)||0,created_by:auth.userId,updated_by:auth.userId}).select("*").single();return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({product:data},{status:201});}if(b?.kind==="addon_product"){const type=b.fulfillmentType==="content"?"content":"physical",key=text(b.addonKey,48).toUpperCase(),name=text(b.name,120),price=Number(b.priceCents);let entitlementId=null;if(type==="content"){const {data:e,error}=await db.from("access_entitlements").insert({program_key:DEFAULT_PROGRAM_KEY,entitlement_key:`CONTENT_${key}`,name,entitlement_type:"content",active:true,created_by:auth.userId,updated_by:auth.userId}).select("id").single();if(error)return NextResponse.json({error:error.message},{status:400});entitlementId=e.id;}const {data,error}=await db.from("addon_products").insert({program_key:DEFAULT_PROGRAM_KEY,addon_key:key,name,description:text(b.description)||null,price_cents:price,currency:"usd",included:price===0,max_quantity:Math.max(1,Number(b.maxQuantity)||10),active:b.active===true,public:b.public===true,available_from:text(b.availableFrom)||null,available_until:text(b.availableUntil)||null,fulfillment_type:type,entitlement_id:entitlementId,created_by:auth.userId,updated_by:auth.userId}).select("*").single();return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({addon:data},{status:201});}if(b?.kind==="complimentary"){const {data,error}=await db.rpc("issue_complimentary_ticket",{p_product_id:text(b.productId,64),p_user_id:text(b.userId,64),p_actor_user_id:auth.userId,p_holder_name:text(b.holderName,120)||null});return error?NextResponse.json({error:error.message},{status:400}):NextResponse.json({ticketId:data},{status:201});}return NextResponse.json({error:"Unsupported action."},{status:400});}
export async function PATCH(request:Request){const auth=await requireOwnerUser();if(!isOwnerAuthed(auth))return ownerAuthFailureResponse(auth);const b=await request.json().catch(()=>null),db=getSupabaseAdmin();if(b?.action==="revoke"){const {data,error}=await db.rpc("revoke_ticket",{p_ticket_id:text(b.ticketId,64),p_actor_user_id:auth.userId});return error||!data?NextResponse.json({error:error?.message||"Ticket cannot be revoked."},{status:409}):NextResponse.json({ok:true});}if(b?.action==="addon_fulfillment"){const status=["pending","ready","distributed"].includes(b.status)?b.status:null;if(!status)return NextResponse.json({error:"Invalid fulfillment state."},{status:400});const {data,error}=await db.from("commerce_order_lines").update({fulfillment_status:status}).eq("id",text(b.lineId,64)).eq("line_type","addon").select("id").maybeSingle();return error||!data?NextResponse.json({error:"Unable to update fulfillment."},{status:400}):NextResponse.json({ok:true});}const table=b?.kind==="ticket_product"?"ticket_products":b?.kind==="addon_product"?"addon_products":null;if(!table)return NextResponse.json({error:"Unsupported action."},{status:400});const {data,error}=await db.from(table).update({active:b.active===true,public:b.public===true,updated_by:auth.userId}).eq("id",text(b.id,64)).eq("program_key",DEFAULT_PROGRAM_KEY).select("id").maybeSingle();return error||!data?NextResponse.json({error:"Unable to update product."},{status:400}):NextResponse.json({ok:true});}

import { NextResponse } from "next/server";
import { resolveServerOrgContext } from "@/lib/org/session-org-context";
import {
  createTravelGroupRequest,
  isTravelGroupRequestValidationError,
  listTravelGroupRequestsForChurch,
  sanitizeTravelGroupRequestCreateInput,
} from "@/lib/travel/group-booking/repository";

const LEADERSHIP_ROLES = new Set(["Pastor", "Overseer"]);

/**
 * GET — list group booking requests for the session church.
 * Unauthenticated → 401. Authenticated without church affiliation → truthful [].
 */
export async function GET(request: Request) {
  const context = await resolveServerOrgContext(request);
  if (!context) {
    return NextResponse.json({ error: "Authentication required." }, { status: 401 });
  }

  if (!context.churchId) {
    return NextResponse.json([], { status: 200 });
  }

  try {
    const data = await listTravelGroupRequestsForChurch(context.churchId);
    return NextResponse.json(data);
  } catch (error) {
    // Safe production log signature that avoids exposing internal Postgres attributes
    console.error("[travel.group-requests] list failed");
    return NextResponse.json({ error: "Failed to load requests." }, { status: 500 });
  }
}

/**
 * POST — Pastor/Overseer create a corporate group request.
 * church_id, requester_id, and status are stamped server-side only.
 */
export async function POST(request: Request) {
  const context = await resolveServerOrgContext(request);
  if (!context) {
    return NextResponse.json({ error: "Authentication required." }, { status: 401 });
  }

  if (!context.churchId || !LEADERSHIP_ROLES.has(context.role)) {
    return NextResponse.json(
      { error: "Pastor or Overseer membership is required." },
      { status: 403 },
    );
  }

  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const sanitized = sanitizeTravelGroupRequestCreateInput(body);
  if (isTravelGroupRequestValidationError(sanitized)) {
    return NextResponse.json({ error: sanitized.error }, { status: sanitized.status });
  }

  try {
    const data = await createTravelGroupRequest({
      churchId: context.churchId,
      requesterId: context.userId,
      ...sanitized,
    });
    return NextResponse.json(data, { status: 201 });
  } catch (error) {
    console.error("[travel.group-requests] create failed", {
      message: error instanceof Error ? error.message : String(error),
    });
    return NextResponse.json(
      { error: "Unable to save group booking request." },
      { status: 500 },
    );
  }
}

