"use client";
import {useCallback,useEffect,useRef,useState} from "react";import {Camera,CameraOff,CheckCircle2,Download,RefreshCw,Search,ShieldAlert,TriangleAlert,XCircle} from "lucide-react";
type Data=any;const input="min-h-12 w-full rounded-lg border border-white/15 bg-black/45 px-3 text-base text-white";
export default function CheckInOperationsClient(){const [data,setData]=useState<Data>({occurrences:[],zones:[],rules:[],scans:[],entitlements:[],stats:{}}),[occurrenceId,setOccurrenceId]=useState(""),[zoneId,setZoneId]=useState(""),[manual,setManual]=useState(""),[result,setResult]=useState<any>(null),[busy,setBusy]=useState(false),[camera,setCamera]=useState<"off"|"active"|"denied"|"unsupported">("off"),[guardian,setGuardian]=useState(false),[search,setSearch]=useState(""),[matches,setMatches]=useState<any[]>([]);const video=useRef<HTMLVideoElement>(null),stream=useRef<MediaStream|null>(null),timer=useRef<number|null>(null);
 const load=useCallback(async()=>{const r=await fetch("/api/owner/check-in",{cache:"no-store"}),j=await r.json();if(r.ok){setData(j);setOccurrenceId((x:string)=>x||j.occurrences[0]?.id||"")}},[]);useEffect(()=>{void load();return()=>stop()},[load]);const availableRules=data.rules.filter((r:any)=>r.event_occurrence_id===occurrenceId);useEffect(()=>{if(!availableRules.some((r:any)=>r.access_zone_id===zoneId))setZoneId(availableRules[0]?.access_zone_id||"")},[occurrenceId,data.rules,zoneId]);
 async function scan(value:string,method:"camera"|"manual"){if(!occurrenceId||!zoneId||busy)return;setBusy(true);setResult(null);try{const r=await fetch("/api/owner/check-in",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({kind:"scan",value,occurrenceId,zoneId,inputMethod:method,guardianPresent:guardian})}),j=await r.json();setResult(j);if(r.ok)setManual("");}catch{setResult({decision:"VALIDATION_UNAVAILABLE",reasonLabel:"Network validation unavailable. Do not admit; retry."})}finally{setBusy(false);await load()}}
 function stop(){if(timer.current)window.clearInterval(timer.current);timer.current=null;stream.current?.getTracks().forEach(t=>t.stop());stream.current=null;setCamera("off")}
 async function start(){if(!navigator.mediaDevices?.getUserMedia){setCamera("unsupported");return}const Detector=(window as any).BarcodeDetector;if(!Detector){setCamera("unsupported");return}try{stream.current=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}},audio:false});if(video.current){video.current.srcObject=stream.current;await video.current.play()}setCamera("active");const detector=new Detector({formats:["qr_code"]});timer.current=window.setInterval(async()=>{if(!video.current||busy)return;try{const codes=await detector.detect(video.current);const value=codes[0]?.rawValue;if(value){stop();await scan(value,"camera")}}catch{}},350)}catch{setCamera("denied")}}
 async function lookup(){const r=await fetch(`/api/owner/check-in?search=${encodeURIComponent(search)}`,{cache:"no-store"}),j=await r.json();setMatches(r.ok?j.results:[])}const selectedOcc=data.occurrences.find((x:any)=>x.id===occurrenceId),selectedRule=availableRules.find((x:any)=>x.access_zone_id===zoneId);const state=result?.decision==="ALLOWED_WITH_CONDITION"||result?.decision==="VALIDATION_UNAVAILABLE"?"amber":result?.decision==="ALLOWED"?"green":"red";
 return <div className="min-w-0"><header className="rounded-xl border border-[#00a8ff]/25 bg-[#07101d] p-4"><p className="text-xs font-black uppercase tracking-[.18em] text-[#00a8ff]">Secure Door Operations</p><h1 className="mt-1 text-3xl font-black">CHECK-IN</h1><p className="mt-2 text-sm text-white/60">Every decision is resolved by the server and recorded. Network failure always fails closed.</p></header>
 <div className="mt-3 grid gap-3 lg:grid-cols-[minmax(0,1.1fr)_minmax(20rem,.9fr)]"><section className="space-y-3 rounded-xl border border-white/10 bg-[#080b14] p-4"><div className="grid gap-3 sm:grid-cols-2"><label className="grid gap-1 text-sm font-bold">Event occurrence<select className={input} value={occurrenceId} onChange={e=>setOccurrenceId(e.target.value)}><option value="">Select event</option>{data.occurrences.map((o:any)=><option key={o.id} value={o.id}>{o.title_override||o.events?.title} · {new Date(o.scheduled_start_at).toLocaleString()}</option>)}</select></label><label className="grid gap-1 text-sm font-bold">Entry zone<select className={input} value={zoneId} onChange={e=>setZoneId(e.target.value)}><option value="">Select zone</option>{availableRules.map((r:any)=><option key={r.id} value={r.access_zone_id}>{r.access_zones?.name} · {r.access_mode}</option>)}</select></label></div><div className="rounded-lg border border-[#f6c344]/25 bg-[#f6c344]/8 p-3"><strong className="block text-[#f6c344]">ACTIVE CONTEXT</strong><span>{selectedOcc?.title_override||selectedOcc?.events?.title||"No event selected"} — {selectedRule?.access_zones?.name||"No zone selected"}</span></div>
 <div className="relative aspect-[4/3] overflow-hidden rounded-xl border-2 border-dashed border-white/20 bg-black"><video ref={video} muted playsInline className="h-full w-full object-cover"/><div className="pointer-events-none absolute inset-[12%] rounded-xl border-2 border-[#00a8ff] shadow-[0_0_30px_rgba(0,168,255,.3)]"/>{camera!=="active"?<div className="absolute inset-0 grid place-items-center text-center text-white/60"><Camera className="mx-auto h-10 w-10"/><p>{camera==="denied"?"Camera permission denied. Use manual entry.":camera==="unsupported"?"QR camera scanning is unsupported in this browser. Use manual entry.":"Camera starts only when requested."}</p></div>:null}</div><div className="grid grid-cols-2 gap-2"><button disabled={!occurrenceId||!zoneId||camera==="active"} onClick={()=>void start()} className="min-h-14 rounded-lg bg-[#00a8ff] font-black text-black"><Camera className="mr-2 inline"/>START SCANNER</button><button onClick={stop} disabled={camera!=="active"} className="min-h-14 rounded-lg border border-white/20 font-black"><CameraOff className="mr-2 inline"/>STOP</button></div>
 <label className="flex min-h-12 items-center gap-2 rounded-lg border border-white/10 p-3"><input type="checkbox" checked={guardian} onChange={e=>setGuardian(e.target.checked)}/>Guardian is physically present (relationship still server-verified)</label><form onSubmit={e=>{e.preventDefault();void scan(manual,"manual")}} className="flex gap-2"><input aria-label="Credential token or badge code" className={input} value={manual} onChange={e=>setManual(e.target.value)} placeholder="Paste secure QR URL/token or badge code"/><button disabled={!manual||!occurrenceId||!zoneId||busy} className="min-w-24 rounded-lg bg-white font-black text-black">VALIDATE</button></form></section>
 <aside className="space-y-3">{result?<section role="status" className={`rounded-xl border-2 p-5 ${state==="green"?"border-emerald-400 bg-emerald-950/55":state==="amber"?"border-amber-400 bg-amber-950/55":"border-red-400 bg-red-950/55"}`}>{state==="green"?<CheckCircle2 className="h-12 w-12"/>:state==="amber"?<TriangleAlert className="h-12 w-12"/>:<XCircle className="h-12 w-12"/>}<h2 className="mt-3 text-3xl font-black">{result.decision==="ALLOWED"?"ACCESS GRANTED":result.decision==="ALLOWED_WITH_CONDITION"?"ACCESS WITH CONDITION":result.reasonCode==="TICKET_ALREADY_USED"?"ALREADY CHECKED IN":result.decision==="VALIDATION_UNAVAILABLE"?"VALIDATION UNAVAILABLE":"ACCESS DENIED"}</h2>{result.attendeeName?<p className="mt-2 text-xl font-bold">{result.attendeeName}</p>:null}{result.productName?<p>{result.productName}</p>:null}<p className="mt-3 font-bold">{result.reasonLabel}</p>{result.preferredUntil?<p>Preferred seating valid until {new Date(result.preferredUntil).toLocaleTimeString()}</p>:null}<button onClick={()=>setResult(null)} className="mt-5 min-h-12 w-full rounded-lg bg-white font-black text-black"><RefreshCw className="mr-2 inline"/>NEXT SCAN</button></section>:<section className="rounded-xl border border-white/10 bg-[#080b14] p-5 text-white/55"><ShieldAlert className="h-10 w-10"/><h2 className="mt-3 text-xl font-black text-white">Ready for validation</h2><p>Select the event and zone before scanning.</p></section>}
