export default function TicketManagementClient(){const [d,setD]=useState<any>({products:[],addons:[],occurrences:[],orders:[],tickets:[],audit:[]}),[q,setQ]=useState(""),[error,setError]=useState("");const load=useCallback(async()=>{const r=await fetch(`/api/owner/tickets?q=${encodeURIComponent(q)}`,{cache:"no-store"});const j=await r.json();if(!r.ok)throw new Error(j.error);setD(j)},[q]);useEffect(()=>{void load().catch(e=>setError(e.message))},[load]);async function send(method:string,body:any){const r=await fetch("/api/owner/tickets",{method,headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error);await load()}async function form(e:React.FormEvent<HTMLFormElement>,kind:string){e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));try{await send("POST",{kind,...f,priceCents:Math.round(Number(f.price)*100),capacity:Number(f.capacity),maxQuantity:Number(f.maxQuantity),perOrderLimit:Number(f.perOrderLimit),active:true,public:true});e.currentTarget.reset()}catch(e){setError(e instanceof Error?e.message:"Unable to save")}}
