"use client";

import { useCallback, useEffect, useState } from "react";
import { fetchLiveAccessEvaluation } from "@/lib/access";
import {
  attendeeStatusMessage,
  isKnownAttendeeStreamId,
  mapBroadcastStateToAttendeeStatus,
  type AttendeeBroadcastStatus,
} from "@/lib/live/attendee-live-honesty";
import { LIVE_STREAM_STATE_BROADCAST_EVENT } from "@/lib/live/types";
import {
  acquirePlatformChannel,
  commitPlatformChannelSubscribe,
  registerPlatformListener,
  releasePlatformChannel,
  unregisterPlatformListener,
} from "@/lib/live/platform-channel";
import { getSupabase } from "@/lib/supabase/client";

export type LiveStreamState = {
  streamId: string;
  status: AttendeeBroadcastStatus;
  statusMessage: string;
  isLive: boolean;
  isLoading: boolean;
  error: string | null;
  /** Omitted — no production-backed viewer metric is exposed here. */
  viewerCount: null;
  videoUrl: string | null;
  posterUrl: string | null;
};

const STREAM_STATE_LISTENER_ID = "use-live-stream-honesty";

export function formatElapsedTime(totalSeconds: number): string {
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  return [hours, minutes, seconds].map((part) => String(part).padStart(2, "0")).join(":");
}

/**
 * Authoritative attendee stream state from /api/access/live + manifest.
 * Never fabricates viewers, chat, or live status.
 */
export function useLiveStream(streamId: string): LiveStreamState {
  const known = isKnownAttendeeStreamId(streamId);
  const [status, setStatus] = useState<AttendeeBroadcastStatus>(
    known ? "loading" : "unavailable",
  );
  const [isLive, setIsLive] = useState(false);
  const [isLoading, setIsLoading] = useState(known);
  const [error, setError] = useState<string | null>(null);
  const [videoUrl, setVideoUrl] = useState<string | null>(null);

  const sync = useCallback(async () => {
    if (!known) {
      setStatus("unavailable");
      setIsLive(false);
      setIsLoading(false);
      setVideoUrl(null);
      return;
    }

    try {
      const evaluation = await fetchLiveAccessEvaluation();
      const nextStatus = mapBroadcastStateToAttendeeStatus(
        evaluation.currentState,
        evaluation.streamIsLive,
      );
      setIsLive(evaluation.streamIsLive);
      setStatus(nextStatus);
      setError(null);

      if (evaluation.streamIsLive && evaluation.canViewStream) {
        const response = await fetch("/api/stream/manifest?experience=main_stage", {
          method: "GET",
          credentials: "include",
          cache: "no-store",
        });
        if (!response.ok) {
          setVideoUrl(null);
          if (response.status !== 404) {
            setStatus("error");
            setError(`Live playback is unavailable (${response.status}).`);
          }
          return;
        }
        const data = (await response.json()) as {
          success?: boolean;
          playbackUrl?: string;
          error?: string;
        };
        const playbackUrl = data.playbackUrl?.trim() ?? "";
        if (data.success && playbackUrl) {
          setVideoUrl(playbackUrl);
        } else {
          setVideoUrl(null);
          setStatus("starting_soon");
        }
      } else {
        setVideoUrl(null);
      }
    } catch (syncError) {
      console.error("Live stream sync failed:", syncError);
      setStatus("error");
      setError("Unable to load live stream status.");
      setVideoUrl(null);
    } finally {
      setIsLoading(false);
    }
  }, [known]);

  useEffect(() => {
    if (!known) {
      setIsLoading(false);
      return;
    }

    setIsLoading(true);
    let cancelled = false;
    let supabase: ReturnType<typeof getSupabase>;

    try {
      supabase = getSupabase();
    } catch {
      queueMicrotask(() => {
        if (!cancelled) {
          setStatus("error");
          setError("Live stream state is unavailable.");
          setIsLoading(false);
        }
      });
      return;
    }

    queueMicrotask(() => {
      if (!cancelled) void sync();
    });

    acquirePlatformChannel(supabase);
    registerPlatformListener(STREAM_STATE_LISTENER_ID, (channel) =>
      channel.on("broadcast", { event: LIVE_STREAM_STATE_BROADCAST_EVENT }, () => {
        if (cancelled) return;
        void sync();
      }),
    );
    commitPlatformChannelSubscribe();

    return () => {
      cancelled = true;
      unregisterPlatformListener(STREAM_STATE_LISTENER_ID);
      releasePlatformChannel(supabase);
    };
  }, [known, sync, streamId]);

  return {
    streamId,
    status,
    statusMessage: error ?? attendeeStatusMessage(status),
    isLive,
    isLoading,
    error,
    viewerCount: null,
    videoUrl,
    posterUrl: null,
  };
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

export type OperatorWebcamPreviewStatus = "idle" | "starting" | "active" | "error";

type UseOperatorWebcamPreviewResult = {
  videoRef: React.RefObject<HTMLVideoElement | null>;
  status: OperatorWebcamPreviewStatus;
  errorMessage: string | null;
  isActive: boolean;
  startPreview: () => Promise<void>;
  stopPreview: () => void;
};

function releaseMediaStream(stream: MediaStream | null, video: HTMLVideoElement | null) {
  if (stream) {
    stream.getTracks().forEach((track) => track.stop());
  }
  if (video) {
    video.srcObject = null;
  }
}

/**
 * Operator-local webcam monitor only — never published to Supabase or attendees.
 */
export function useOperatorWebcamPreview(): UseOperatorWebcamPreviewResult {
  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const [status, setStatus] = useState<OperatorWebcamPreviewStatus>("idle");
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const stopPreview = useCallback(() => {
    releaseMediaStream(streamRef.current, videoRef.current);
    streamRef.current = null;
    setStatus("idle");
    setErrorMessage(null);
  }, []);

  const startPreview = useCallback(async () => {
    stopPreview();
    setStatus("starting");
    setErrorMessage(null);

    try {
      if (!navigator.mediaDevices?.getUserMedia) {
        throw new Error("Camera API is not available in this browser.");
      }

      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
        audio: true,
      });

      streamRef.current = stream;

      const video = videoRef.current;
      if (video) {
        video.srcObject = stream;
        await video.play().catch(() => {
          /* Muted inline preview — autoplay should succeed. */
        });
      }

      setStatus("active");
    } catch (error) {
      releaseMediaStream(streamRef.current, videoRef.current);
      streamRef.current = null;
      setStatus("error");
      setErrorMessage(
        error instanceof Error
          ? error.message
          : "Camera permission denied or hardware unavailable.",
      );
    }
  }, [stopPreview]);

  useEffect(() => {
    return () => {
      releaseMediaStream(streamRef.current, videoRef.current);
      streamRef.current = null;
    };
  }, []);

  return {
    videoRef,
    status,
    errorMessage,
    isActive: status === "active",
    startPreview,
    stopPreview,
  };
}

import "server-only";
import { credentialTokenHashHex, isValidCredentialToken } from "@/lib/credentials/token";
import { getSupabaseAdmin } from "@/lib/supabase/server";
import { DEFAULT_PROGRAM_KEY } from "@/lib/registration/types";

export const SCAN_REASON_LABELS:Record<string,string>={VALID_REGISTRATION:"Valid registration",VALID_TICKET:"Valid ticket",PREFERRED_SEATING:"Preferred seating",GENERAL_SEATING:"General seating",PREFERRED_WINDOW_EXPIRED:"Preferred seating hold period has ended; route to general seating",MUSICAL_TICKET_REQUIRED:"A valid Musical ticket is required",WRONG_EVENT:"Credential is for a different event",WRONG_ZONE:"Credential does not permit this access zone",CREDENTIAL_REVOKED:"Credential is revoked or expired",REGISTRATION_CANCELED:"Registration is canceled or refunded",PAYMENT_NOT_CONFIRMED:"Payment is not confirmed",TICKET_REVOKED:"Ticket is revoked, refunded, or expired",TICKET_ALREADY_USED:"Already checked in",ENTITLEMENT_EXPIRED:"Entitlement has expired",GUARDIAN_REQUIRED:"Guardian required",NOT_YET_VALID:"Credential is not yet valid",INVALID_CREDENTIAL:"Credential was not recognized",NO_APPLICABLE_ENTITLEMENT:"No applicable entitlement"};

export function extractCredentialReference(value:string){
  const raw=value.trim();
  if(/^CS26-[A-Z0-9]{8}$/i.test(raw))return {hash:"",reference:raw.toUpperCase()};
  if(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(raw))return {hash:"",reference:raw.toLowerCase()};
  let token=raw;try{const url=new URL(raw);token=url.pathname.split("/").filter(Boolean).at(-1)||"";}catch{}
  return isValidCredentialToken(token)?{hash:credentialTokenHashHex(token),reference:""}:null;
}

export async function processAccessScan(input:{value:string;occurrenceId:string;zoneId:string;scannerUserId:string;inputMethod:"camera"|"manual";guardianPresent?:boolean}){
  const ref=extractCredentialReference(input.value);if(!ref)return {decision:"DENIED",reasonCode:"INVALID_CREDENTIAL",entryRecorded:false};
  const {data,error}=await getSupabaseAdmin().rpc("process_access_scan",{p_token_hash_hex:ref.hash,p_reference:ref.reference,p_occurrence_id:input.occurrenceId,p_zone_id:input.zoneId,p_scanner_user_id:input.scannerUserId,p_input_method:input.inputMethod,p_guardian_present:input.guardianPresent===true});
  if(error)throw error;return data;
}

export async function loadCheckInOperations(){const db=getSupabaseAdmin(),now=new Date(),from=new Date(now.getTime()-12*60*60*1000).toISOString(),to=new Date(now.getTime()+36*60*60*1000).toISOString();const [occurrences,zones,rules,scans,entitlements]=await Promise.all([
  db.from("event_occurrences").select("id,title_override,scheduled_start_at,scheduled_end_at,status,venue_label,events(title,event_type)").eq("visibility","published").neq("status","canceled").gte("scheduled_start_at",from).lte("scheduled_start_at",to).order("scheduled_start_at"),
  db.from("access_zones").select("id,zone_key,name,description,active").eq("program_key",DEFAULT_PROGRAM_KEY).order("name"),
  db.from("occurrence_access_rules").select("id,event_occurrence_id,access_zone_id,entitlement_id,access_mode,usage_mode,allow_general_fallback,active,access_zones(name,zone_key),access_entitlements(name,entitlement_key)").eq("active",true),
  db.from("access_scan_attempts").select("id,scanned_at,decision,reason_code,credential_type,event_occurrence_id,access_zone_id,scanner_user_id,entry_recorded,registrations(first_name,last_name,registration_products(name)),ticket_instances(holder_name,ticket_products(name)),event_occurrences(title_override,events(title)),access_zones(name)").eq("program_key",DEFAULT_PROGRAM_KEY).order("scanned_at",{ascending:false}).limit(100),
  db.from("access_entitlements").select("id,name,entitlement_key,event_type,access_zone").eq("program_key",DEFAULT_PROGRAM_KEY).eq("active",true).in("entitlement_type",["event_access","seating"])
]);
  const rows=scans.data??[];const stats={total:rows.length,granted:rows.filter((x:any)=>x.decision.startsWith("ALLOWED")).length,denied:rows.filter((x:any)=>x.decision==="DENIED").length,alreadyUsed:rows.filter((x:any)=>x.reason_code==="TICKET_ALREADY_USED").length,checkedIn:rows.filter((x:any)=>x.entry_recorded).length};
  const countBy=(label:(row:any)=>string)=>Object.entries(rows.reduce((all:Record<string,number>,row:any)=>{const key=label(row)||"Unknown";all[key]=(all[key]||0)+1;return all},{})).map(([label,count])=>({label,count})).sort((a,b)=>b.count-a.count);
  const breakdowns={byEvent:countBy((x:any)=>x.event_occurrences?.title_override||x.event_occurrences?.events?.title),byProduct:countBy((x:any)=>x.registrations?.registration_products?.name||x.ticket_instances?.ticket_products?.name),byCredential:countBy((x:any)=>x.credential_type)};
  return {occurrences:occurrences.data??[],zones:zones.data??[],rules:rules.data??[],scans:rows,entitlements:entitlements.data??[],stats,breakdowns};
}

export async function searchOperationalCredentials(query:string){const q=query.trim().slice(0,100);if(q.length<2)return[];const db=getSupabaseAdmin();const [{data:regs},{data:tickets}]=await Promise.all([
  db.from("registrations").select("id,first_name,last_name,confirmation_reference,status,registration_products(name),registration_credentials(badge_code,status)").eq("program_key",DEFAULT_PROGRAM_KEY).or(`first_name.ilike.%${q}%,last_name.ilike.%${q}%,confirmation_reference.ilike.%${q}%`).limit(12),
  db.from("ticket_instances").select("id,holder_name,status,ticket_products(name,event_occurrences(title_override,events(title)))").or(`holder_name.ilike.%${q}%,id.eq.${/^[0-9a-f-]{36}$/i.test(q)?q:"00000000-0000-0000-0000-000000000000"}`).limit(12)
]);return [...(regs??[]).map((x:any)=>({type:"registration",id:x.id,name:`${x.first_name} ${x.last_name}`,reference:x.registration_credentials?.[0]?.badge_code,status:x.status,product:x.registration_products?.name})),...(tickets??[]).map((x:any)=>({type:"ticket",id:x.id,name:x.holder_name||"Ticket holder",reference:x.id,status:x.status,product:x.ticket_products?.name}))];}

import assert from "node:assert/strict";
import { describe, it, beforeEach } from "node:test";

import {
  collapseToPublicView,
  resolvedPublicFieldAllowlist,
  shouldIssueCredentialSession,
  toSessionPayload,
} from "@/lib/credentials/public-outcome";
import type { SafeCredentialResolution } from "@/lib/credentials/types";

describe("public credential outcome collapsing", () => {
  const resolved: SafeCredentialResolution = {
    outcome: "resolved",
    status: "active",
    badgeCode: "CS26-A1B2C3D4",
    firstName: "Jordan",
    churchName: "Temple of Hope",
    jurisdiction: "Texas Southwest",
    programKey: "cogic-stream-2026",
  };

  it("issues session only for resolved usable credentials", () => {
    assert.equal(shouldIssueCredentialSession(resolved), true);
    assert.equal(
      shouldIssueCredentialSession({ ...resolved, outcome: "revoked" }),
      false,
    );
    assert.equal(
      shouldIssueCredentialSession({ ...resolved, status: undefined }),
      false,
    );
  });

  it("collapses invalid states into unavailable", () => {
    for (const outcome of ["invalid", "rotated", "revoked", "expired", "unavailable"] as const) {
      const view = collapseToPublicView({ ...resolved, outcome });
      assert.equal(view.kind, "unavailable");
    }
  });

  it("allowlists only safe public fields", () => {
    assert.deepEqual(resolvedPublicFieldAllowlist(), [
      "status",
      "badgeCode",
      "firstName",
      "churchName",
      "jurisdiction",
      "programKey",
    ]);
    const payload = toSessionPayload(
      resolved as SafeCredentialResolution & {
        outcome: "resolved";
        status: "issued" | "active";
      },
    );
    assert.deepEqual(Object.keys(payload).sort(), resolvedPublicFieldAllowlist().slice().sort());
  });
});

import { AWAKENING_CONCERT_BACKDROP_ART } from "@/lib/experience/awakening-dashboard-assets";

/** Single mobile-first dashboard backdrop — normalized Y (0–1) in the asset. */
export type BackdropVariant = "mobile";

const CONCERT_BACKDROP = {
  width: AWAKENING_CONCERT_BACKDROP_ART.width,
  height: AWAKENING_CONCERT_BACKDROP_ART.height,
  beamYN: 0.512,
  heroStackAnchorYN: 0.478,
  cardRowYN: 0.618,
} as const;

export function normalizeBackdropVariant(
  _variant: string | undefined | null,
): BackdropVariant {
  return "mobile";
}

export const BACKDROP_HEIGHT_SCALE = 1;

export const HERO_STACK_LAYOUT_VERSION = 41;

export const HERO_STACK_LIFT_PX = 148;

type ObjectPositionFractions = { posX: number; posY: number };

export function parseObjectPosition(value: string): ObjectPositionFractions {
  const parts = value.trim().split(/\s+/);
  const axis = (token: string, defaultCenter: boolean): number => {
    if (token === "left" || token === "top") return 0;
    if (token === "right" || token === "bottom") return 1;
    if (token === "center") return 0.5;
    if (token.endsWith("%")) return parseFloat(token) / 100;
    return defaultCenter ? 0.5 : 0;
  };

  if (parts.length === 1) {
    const lone = parts[0];
    if (lone === "top" || lone === "bottom") return { posX: 0.5, posY: axis(lone, false) };
    if (lone === "left" || lone === "right") return { posX: axis(lone, false), posY: 0.5 };
    return { posX: axis(lone, true), posY: 0.5 };
  }

  return { posX: axis(parts[0], true), posY: axis(parts[1], false) };
}

export function backdropContainerHeightPx(viewportHeight: number): number {
  return viewportHeight * BACKDROP_HEIGHT_SCALE;
}

function backdropCoverScale(
  boxWidth: number,
  boxHeight: number,
  naturalWidth: number,
  naturalHeight: number,
): number {
  return Math.max(boxWidth / naturalWidth, boxHeight / naturalHeight);
}

function backdropObjectScale(
  boxWidth: number,
  boxHeight: number,
  naturalWidth: number,
  naturalHeight: number,
  objectFit: string,
): number {
  if (objectFit === "contain") {
    return Math.min(boxWidth / naturalWidth, boxHeight / naturalHeight);
  }
  if (objectFit === "fill") {
    return Math.max(boxWidth / naturalWidth, boxHeight / naturalHeight);
  }
  return backdropCoverScale(boxWidth, boxHeight, naturalWidth, naturalHeight);
}

function backdropCoverScaleForViewport(viewportWidth: number, viewportHeight: number): number {
  const { width, height } = CONCERT_BACKDROP;
  return Math.max(viewportWidth / width, viewportHeight / height);
}

export type DashboardBackdropMedia = HTMLVideoElement | HTMLImageElement;

export function queryDashboardBackdropMedia(): HTMLVideoElement | null {
  if (typeof document === "undefined") return null;
  return document.querySelector<HTMLVideoElement>('[data-backdrop-variant="mobile"]');
}

export function getBackdropNaturalDimensions(media: DashboardBackdropMedia): {
  width: number;
  height: number;
} {
  if (media instanceof HTMLVideoElement) {
    return { width: media.videoWidth, height: media.videoHeight };
  }
  return { width: media.naturalWidth, height: media.naturalHeight };
}

export function isDashboardBackdropMediaReady(media: DashboardBackdropMedia | null | undefined): boolean {
  if (!media || media.clientHeight <= 0) return false;
  const { width, height } = getBackdropNaturalDimensions(media);
  if (width > 0 && height > 0) return true;
  if (media instanceof HTMLVideoElement) {
    return media.readyState >= HTMLMediaElement.HAVE_CURRENT_DATA;
  }
  return media.complete;
}

function backdropFillRowTopPx(
  media: DashboardBackdropMedia | null | undefined,
  rowYN: number,
): number {
  if (!media) return 0;
  const rect = media.getBoundingClientRect();
  if (rect.height <= 0) return 0;
  return rect.top + rowYN * rect.height;
}

/** Map normalized art row (0–1) to viewport px for object-fit cover/contain/fill. */
export function backdropCoverRowTopPx(
  media: DashboardBackdropMedia | null | undefined,
  rowYN: number,
): number {
  if (!media) return 0;
  const style = window.getComputedStyle(media);
  if (style.objectFit === "fill") {
    return backdropFillRowTopPx(media, rowYN);
  }

  const { width: naturalWidth, height: naturalHeight } = getBackdropNaturalDimensions(media);
  const { clientWidth, clientHeight } = media;
  if (!naturalWidth || !naturalHeight || !clientWidth || !clientHeight) return 0;

  const scale = backdropObjectScale(
    clientWidth,
    clientHeight,
    naturalWidth,
    naturalHeight,
    style.objectFit,
  );
  const renderedH = naturalHeight * scale;
  const rect = media.getBoundingClientRect();
  const { posY } = parseObjectPosition(style.objectPosition);
  const offsetY = (clientHeight - renderedH) * posY;

  return rect.top + offsetY + rowYN * renderedH;
}

export function backdropCoverMetrics(img: HTMLImageElement | null | undefined) {
  if (!img) {
    return {
      objectFit: "",
      objectPosition: "",
      posX: 0,
      posY: 0,
      scale: 0,
      overflow: { x: 0, y: 0 },
      estimatedTopCropPx: 0,
      topPreserved: true,
      heightScale: BACKDROP_HEIGHT_SCALE,
      expectedClientH: 0,
      clientHeightDelta: 0,
    };
  }

  const { naturalWidth, naturalHeight, clientWidth, clientHeight } = img;
  const style = window.getComputedStyle(img);
  const { posX, posY } = parseObjectPosition(style.objectPosition);
  const scale =
    naturalWidth > 0 && naturalHeight > 0
      ? backdropCoverScale(clientWidth, clientHeight, naturalWidth, naturalHeight)
      : 0;
  const renderedH = naturalHeight * scale;
  const overflowY = Math.max(0, renderedH - clientHeight);

  return {
    objectFit: style.objectFit,
    objectPosition: style.objectPosition,
    posX,
    posY,
    scale: Number(scale.toFixed(4)),
    overflow: {
      x: Math.round(Math.max(0, naturalWidth * scale - clientWidth)),
      y: Math.round(overflowY),
    },
    estimatedTopCropPx: Math.round(overflowY * posY),
    topPreserved: Math.round(overflowY * posY) <= 4,
    heightScale: BACKDROP_HEIGHT_SCALE,
    expectedClientH: Math.round(window.innerHeight * BACKDROP_HEIGHT_SCALE),
    clientHeightDelta: Math.round(clientHeight - window.innerHeight * BACKDROP_HEIGHT_SCALE),
  };
}

function backdropScale(viewportWidth: number, viewportHeight: number): number {
  const { width, height } = CONCERT_BACKDROP;
  const boxHeight = backdropContainerHeightPx(viewportHeight);
  return Math.max(viewportWidth / width, boxHeight / height);
}

export function concertBeamTopPx(viewportWidth: number, viewportHeight: number): number {
  const scale = backdropCoverScaleForViewport(viewportWidth, viewportHeight);
  return CONCERT_BACKDROP.beamYN * CONCERT_BACKDROP.height * scale;
}

export function resolveActiveBackdropVariant(): BackdropVariant {
  return "mobile";
}

export function concertBeamTopFromBackdropMedia(media: DashboardBackdropMedia): number {
  return backdropCoverRowTopPx(media, CONCERT_BACKDROP.beamYN);
}

/** @deprecated Use concertBeamTopFromBackdropMedia */
export function concertBeamTopFromBackdropImg(img: HTMLImageElement): number {
  return concertBeamTopFromBackdropMedia(img);
}

function rowTopFromBackdropMedia(
  media: DashboardBackdropMedia,
  rowKey: "beamYN" | "cardRowYN" | "heroStackAnchorYN",
): number {
  const rowYN = CONCERT_BACKDROP[rowKey];
  const { width: naturalWidth, height: naturalHeight } = getBackdropNaturalDimensions(media);
  if (!naturalWidth || !naturalHeight) {
    const vh = window.innerHeight;
    const vw = window.innerWidth;
    return rowYN * CONCERT_BACKDROP.height * backdropScale(vw, vh);
  }
  return backdropCoverRowTopPx(media, rowYN);
}

export function concertCardRowTopFromBackdropMedia(media: DashboardBackdropMedia): number {
  return rowTopFromBackdropMedia(media, "cardRowYN");
}

/** @deprecated Use concertCardRowTopFromBackdropMedia */
export function concertCardRowTopFromBackdropImg(img: HTMLImageElement): number {
  return concertCardRowTopFromBackdropMedia(img);
}

export function concertCardRowTopPx(viewportWidth: number, viewportHeight: number): number {
  const scale = backdropCoverScaleForViewport(viewportWidth, viewportHeight);
  return CONCERT_BACKDROP.cardRowYN * CONCERT_BACKDROP.height * scale;
}

export function concertHeroStackAnchorTopFromBackdropMedia(media: DashboardBackdropMedia): number {
  return rowTopFromBackdropMedia(media, "heroStackAnchorYN");
}

/** @deprecated Use concertHeroStackAnchorTopFromBackdropMedia */
export function concertHeroStackAnchorTopFromBackdropImg(img: HTMLImageElement): number {
  return concertHeroStackAnchorTopFromBackdropMedia(img);
}

export function concertHeroStackAnchorTopPx(viewportWidth: number, viewportHeight: number): number {
  const scale = backdropCoverScaleForViewport(viewportWidth, viewportHeight);
  return CONCERT_BACKDROP.heroStackAnchorYN * CONCERT_BACKDROP.height * scale;
}

export function dashboardHeroStackTopPx(anchorTopPx: number): number {
  return Math.round(anchorTopPx + 10 - HERO_STACK_LIFT_PX);
}

export function dashboardHeroFaceFloorTopPx(anchorTopPx: number): number {
  return Math.round(anchorTopPx - 32 + 6);
}

export function dashboardHeadlineBlockTopPx(
  cardRowTopPx: number,
  extentBelowHeadlineCenterPx: number,
  clearancePx = 40,
): number {
  return Math.round(cardRowTopPx - clearancePx - extentBelowHeadlineCenterPx);
}

export function concertBeamMeta(viewportWidth: number, viewportHeight: number) {
  const scale = backdropScale(viewportWidth, viewportHeight);
  return {
    variant: "mobile" as const,
    beamYN: CONCERT_BACKDROP.beamYN,
    beamSourceY: Math.round(CONCERT_BACKDROP.beamYN * CONCERT_BACKDROP.height),
    scale: Number(scale.toFixed(4)),
    beamTopPx: Math.round(CONCERT_BACKDROP.beamYN * CONCERT_BACKDROP.height * scale),
    asset: { width: CONCERT_BACKDROP.width, height: CONCERT_BACKDROP.height },
  };
}

