"use client";

import type { RealtimeChannel, SupabaseClient } from "@supabase/supabase-js";
import {
  logRealtimeSubscribeStatus,
  removeChannelsByName,
} from "@/lib/live/realtime-subscribe";
import { LIVE_ROOM_PLATFORM_CHANNEL } from "@/lib/live/types";

export type PlatformChannelStatusListener = (status: string, err?: Error) => void;

const platformStatusListeners = new Set<PlatformChannelStatusListener>();

/** Subscribe to shared platform channel subscribe() status updates (for polling fallback). */
export function subscribePlatformChannelStatus(
  listener: PlatformChannelStatusListener,
): () => void {
  platformStatusListeners.add(listener);
  return () => {
    platformStatusListeners.delete(listener);
  };
}

function emitPlatformChannelStatus(status: string, err?: Error): void {
  logRealtimeSubscribeStatus(LIVE_ROOM_PLATFORM_CHANNEL, status, err);
  for (const listener of platformStatusListeners) {
    listener(status, err);
  }
}

export type PlatformListenerApply = (channel: RealtimeChannel) => RealtimeChannel;

let platformChannel: RealtimeChannel | null = null;
let platformSupabase: SupabaseClient | null = null;
let isSubscribed = false;
let subscriberCount = 0;
let syncTimer: ReturnType<typeof setTimeout> | null = null;
let syncChain: Promise<void> = Promise.resolve();
const listeners = new Map<string, PlatformListenerApply>();

function clearSyncTimer(): void {
  if (syncTimer !== null) {
    clearTimeout(syncTimer);
    syncTimer = null;
  }
}

function applyAllListeners(channel: RealtimeChannel): RealtimeChannel {
  let next = channel;
  for (const apply of listeners.values()) {
    next = apply(next);
  }
  return next;
}

async function syncPlatformChannel(): Promise<void> {
  if (!platformSupabase || subscriberCount === 0) {
    if (platformSupabase && platformChannel) {
      await removeChannelsByName(platformSupabase, LIVE_ROOM_PLATFORM_CHANNEL);
    }
    platformChannel = null;
    isSubscribed = false;
    return;
  }

  if (listeners.size === 0) {
    return;
  }

  await removeChannelsByName(platformSupabase, LIVE_ROOM_PLATFORM_CHANNEL);

  let channel = platformSupabase.channel(LIVE_ROOM_PLATFORM_CHANNEL);
  channel = applyAllListeners(channel);
  channel.subscribe((status, err) => {
    emitPlatformChannelStatus(status, err);
    if (status === "CHANNEL_ERROR" || status === "TIMED_OUT") {
      isSubscribed = false;
    } else if (status === "SUBSCRIBED") {
      isSubscribed = true;
    }
  });
  platformChannel = channel;
}

function schedulePlatformChannelSync(): void {
  clearSyncTimer();

  syncTimer = setTimeout(() => {
    syncTimer = null;
    syncChain = syncChain
      .then(() => syncPlatformChannel())
      .catch((error) => {
        console.error("Platform channel sync failed:", error);
        isSubscribed = false;
        platformChannel = null;
      });
  }, 0);
}

/** Shared live-room Realtime channel — one WebSocket for stream sync and seed wallets. */
export function acquirePlatformChannel(supabase: SupabaseClient): RealtimeChannel {
  if (platformChannel && platformSupabase !== supabase) {
    clearSyncTimer();
    listeners.clear();
    void removeChannelsByName(platformSupabase, LIVE_ROOM_PLATFORM_CHANNEL);
    platformChannel = null;
    isSubscribed = false;
    subscriberCount = 0;
  }

  platformSupabase = supabase;

  if (!platformChannel) {
    platformChannel = supabase.channel(LIVE_ROOM_PLATFORM_CHANNEL);
  }

  subscriberCount += 1;

  return platformChannel;
}

export function registerPlatformListener(id: string, apply: PlatformListenerApply): void {
  listeners.set(id, apply);
  schedulePlatformChannelSync();
}

export function unregisterPlatformListener(id: string): void {
  if (!listeners.has(id)) return;

  listeners.delete(id);
  schedulePlatformChannelSync();
}

/** Batch listener registration in the same commit, then bind + subscribe on a fresh channel. */
export function commitPlatformChannelSubscribe(): void {
  schedulePlatformChannelSync();
}

export function releasePlatformChannel(supabase: SupabaseClient): void {
  subscriberCount = Math.max(0, subscriberCount - 1);

  if (subscriberCount === 0) {
    clearSyncTimer();
    listeners.clear();
    syncChain = syncChain
      .then(async () => {
        await removeChannelsByName(supabase, LIVE_ROOM_PLATFORM_CHANNEL);
        platformChannel = null;
        platformSupabase = null;
        isSubscribed = false;
      })
      .catch((error) => {
        console.error("Platform channel release failed:", error);
      });
  } else {
    schedulePlatformChannelSync();
  }
}

import "server-only";

import { getUserFromSession } from "@/lib/auth/session";
import { isApplicationOwnerEmail } from "@/lib/access/admin-prep-override";
import { getSupabaseAdmin } from "@/lib/supabase/server";

export type ChurchOrgRole = "Pastor" | "Overseer" | "Traveler";

export interface ChurchOrgContext {
  userId: string;
  email: string;
  churchId: string | null;
  churchName: string | null;
  role: "Pastor" | "Overseer" | "Traveler";
  isPlatformOwner: boolean;
}

type MembershipLookupRow = {
  role: string | null;
  church_id: string | null;
  updated_at: string | null;
  church_organizations:
    | { id: string; name: string | null }
    | { id: string; name: string | null }[]
    | null;
};

const ROLE_PRIORITY: Record<ChurchOrgRole, number> = {
  Pastor: 3,
  Overseer: 2,
  Traveler: 1,
};

function asChurchOrgRole(value: string | null | undefined): ChurchOrgRole | null {
  if (value === "Pastor" || value === "Overseer" || value === "Traveler") {
    return value;
  }
  return null;
}

function organizationFromRow(
  value: MembershipLookupRow["church_organizations"],
): { id: string; name: string | null } | null {
  if (Array.isArray(value)) {
    return value[0] ?? null;
  }
  return value ?? null;
}

function pickActiveMembership(rows: MembershipLookupRow[]): {
  churchId: string;
  churchName: string | null;
  role: ChurchOrgRole;
} | null {
  const ranked: Array<{
    churchId: string;
    churchName: string | null;
    role: ChurchOrgRole;
    updatedAt: number;
  }> = [];

  for (const row of rows) {
    const role = asChurchOrgRole(row.role);
    const organization = organizationFromRow(row.church_organizations);
    const churchId = organization?.id ?? row.church_id;
    if (!role || !churchId) {
      continue;
    }
    ranked.push({
      churchId,
      churchName: organization?.name?.trim() || null,
      role,
      updatedAt: row.updated_at ? Date.parse(row.updated_at) : 0,
    });
  }

  if (ranked.length === 0) {
    return null;
  }

  ranked.sort((left, right) => {
    const roleDelta = ROLE_PRIORITY[right.role] - ROLE_PRIORITY[left.role];
    if (roleDelta !== 0) {
      return roleDelta;
    }
    return right.updatedAt - left.updatedAt;
  });

  const active = ranked[0];
  return {
    churchId: active.churchId,
    churchName: active.churchName,
    role: active.role,
  };
}

/**
 * Server-authoritative church affiliation + role context.
 * Identity comes only from verified Supabase auth cookies via getUserFromSession().
 * Never trusts request body/query for userId, churchId, or role.
 *
 * isPlatformOwner is evaluated from process.env.ADMIN_EMAILS only (comma-separated).
 * Request is accepted for route-handler signature compatibility; privilege inputs are
 * never read from it — Next SSR cookies are the sole auth source.
 */
export async function resolveServerOrgContext(
  _req: Request,
): Promise<ChurchOrgContext | null> {
  // getUserFromSession() has no Request arg in this codebase; cookies are read via SSR client.
  const user = await getUserFromSession();
  const userId = user?.id?.trim() ?? "";
  const email = user?.email?.trim().toLowerCase() ?? "";

  if (!userId || !email) {
    return null;
  }

  // Server-authoritative application owner evaluation (ADMIN_EMAILS allowlist).
  const isPlatformOwner = isApplicationOwnerEmail(email);

  const { data, error } = await getSupabaseAdmin()
    .from("church_memberships")
    .select("role,church_id,updated_at,church_organizations(id,name)")
    .eq("user_id", userId);

  if (error) {
    console.error("[org.session] church_memberships lookup failed", {
      code: error.code,
      message: error.message,
    });
    return {
      userId,
      email,
      churchId: null,
      churchName: null,
      role: "Traveler",
      isPlatformOwner,
    };
  }

  const active = pickActiveMembership((data ?? []) as MembershipLookupRow[]);
  if (!active) {
    return {
      userId,
      email,
      churchId: null,
      churchName: null,
      role: "Traveler",
      isPlatformOwner,
    };
  }

  return {
    userId,
    email,
    churchId: active.churchId,
    churchName: active.churchName,
    role: active.role,
    isPlatformOwner,
  };
}

import assert from "node:assert/strict";
import test from "node:test";
import type { FeedState, IngestProfileStatus } from "@/lib/owner/contracts";
import { buildPreflightChecks, preflightHasBlockers } from "@/lib/owner/preflight";
import { detectBroadcastProvider, isProductionPlaybackUrl, resolveSafeIngestProfile } from "@/lib/owner/provider-config";

const IVS_URL = "https://example.us-east-1.playback.live-video.net/api/video/v1/us-east-1.123.channel.m3u8";

function feed(primaryUrl: string | null, backupUrl: string | null = null): FeedState {
  return {
    activeSource: "offline",
    primary: { provider: primaryUrl ? detectBroadcastProvider(primaryUrl) : "ivs", hlsUrl: primaryUrl, manifestReachable: false, detail: null },
    backup: { provider: "external", hlsUrl: backupUrl, manifestReachable: false, detail: null },
  };
}

function ingest(playbackConfigured = true): IngestProfileStatus {
  return { provider: "ivs", protocol: "rtmps", ingestConfigured: true, playbackConfigured, channelConfigured: true, recordingConfigured: true, recordingActive: false, backupConfigured: false, crewConnectionReady: playbackConfigured };
}

function checks(primaryUrl: string | null, options: { devFallback?: boolean; mode?: "external_hls" | "rtmp_encoder" } = {}) {
  return buildPreflightChecks({
    eventPhase: { phase: "idle", startTime: null, endTime: null, scheduleTimezone: null },
    countdownConfig: { is_active: false } as never,
    streamState: { id: "global", publish_mode: options.mode ?? "external_hls" } as never,
    hlsProbe: { envConfigured: Boolean(primaryUrl), hlsUrl: primaryUrl, manifestReachable: false, detail: null },
    requestedMode: options.mode ?? "external_hls",
    provider: "ivs",
    ingest: ingest(Boolean(primaryUrl)),
    feed: feed(primaryUrl),
    production: true,
    devFallbackEnabled: options.devFallback ?? false,
    vmix: null,
  });
}

test("IVS configured without Restream passes required configuration checks", () => {
  const result = checks(IVS_URL);
  assert.equal(preflightHasBlockers(result), false);
  assert.equal(result.find((item) => item.id === "feed_primary")?.provider, "ivs");
});

test("IVS configured without vMix passes because vMix is optional", () => {
  const result = checks(IVS_URL, { mode: "rtmp_encoder" });
  const vmix = result.find((item) => item.id === "vmix_api");
  assert.equal(vmix?.required, false);
  assert.equal(preflightHasBlockers(result), false);
});

test("missing primary IVS URL blocks", () => assert.equal(preflightHasBlockers(checks(null)), true));
test("Mux demo URL is rejected", () => assert.equal(isProductionPlaybackUrl("https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8"), false));
test("real HTTPS IVS URL is production-safe", () => assert.equal(isProductionPlaybackUrl(IVS_URL), true));
test("absent backup does not block", () => assert.equal(checks(IVS_URL).find((item) => item.id === "feed_backup")?.required, false));
test("development fallback enabled in production blocks", () => assert.equal(preflightHasBlockers(checks(IVS_URL, { devFallback: true })), true));
test("Restream is not required when provider is IVS", () => assert.equal(checks(IVS_URL).some((item) => /Restream/.test(item.label)), false));
test("optional failure does not block", () => assert.equal(preflightHasBlockers([{ id: "optional", label: "Optional", status: "fail", required: false }]), false));
test("required failure blocks", () => assert.equal(preflightHasBlockers([{ id: "required", label: "Required", status: "fail", required: true }]), true));

function withIvsEnv(values: Record<string, string | undefined>, run: () => void) {
  const keys = Object.keys(values);
  const before = Object.fromEntries(keys.map((key) => [key, process.env[key]]));
  for (const [key, value] of Object.entries(values)) value === undefined ? delete process.env[key] : process.env[key] = value;
  try { run(); } finally {
    for (const [key, value] of Object.entries(before)) value === undefined ? delete process.env[key] : process.env[key] = value;
  }
}

test("RTMPS selection is ready without SRT configuration", () => withIvsEnv({
  BROADCAST_PRIMARY_PROVIDER: "ivs", AWS_IVS_INGEST_PROTOCOL: "rtmps",
  AWS_IVS_INGEST_SERVER: "configured", AWS_IVS_STREAM_KEY: "secret",
  AWS_IVS_SRT_ENDPOINT: undefined, AWS_IVS_SRT_PASSPHRASE: undefined,
}, () => assert.equal(resolveSafeIngestProfile(IVS_URL, null).protocol, "rtmps")));

test("missing RTMPS stream key blocks ingest readiness", () => withIvsEnv({
  BROADCAST_PRIMARY_PROVIDER: "ivs", AWS_IVS_INGEST_PROTOCOL: "rtmps",
  AWS_IVS_INGEST_SERVER: "configured", AWS_IVS_STREAM_KEY: undefined,
}, () => assert.equal(resolveSafeIngestProfile(IVS_URL, null).ingestConfigured, false)));

test("selected SRT requires its complete profile", () => withIvsEnv({
  BROADCAST_PRIMARY_PROVIDER: "ivs", AWS_IVS_INGEST_PROTOCOL: "srt",
  AWS_IVS_SRT_ENDPOINT: "configured", AWS_IVS_SRT_PORT: "9000",
  AWS_IVS_SRT_STREAM_ID: "configured", AWS_IVS_SRT_PASSPHRASE: undefined,
  AWS_IVS_INGEST_SERVER: "configured", AWS_IVS_STREAM_KEY: "secret",
}, () => assert.equal(resolveSafeIngestProfile(IVS_URL, null).ingestConfigured, false)));

test("recording configured remains inactive while encoder is offline", () => withIvsEnv({
  BROADCAST_PRIMARY_PROVIDER: "ivs", AWS_IVS_RECORDING_ENABLED: "true",
}, () => {
  const profile = resolveSafeIngestProfile(IVS_URL, null, false);
  assert.equal(profile.recordingConfigured, true);
  assert.equal(profile.recordingActive, false);
}));

