export async function fulfillTicketCheckout(session:Stripe.Checkout.Session,db:SupabaseClient){const orderId=session.metadata?.order_id,program=session.metadata?.program_key,userId=session.metadata?.user_id;if(session.metadata?.checkout_type!=="ticket_purchase"||!orderId||program!==DEFAULT_PROGRAM_KEY||!userId||session.client_reference_id!==userId)return {ok:false as const,status:422,error:"Ticket checkout metadata invalid."};const {data:order}=await db.from("commerce_orders").select("id,purchaser_user_id,amount_cents,stripe_session_id,status").eq("id",orderId).eq("stripe_session_id",session.id).maybeSingle();if(!order||order.purchaser_user_id!==userId||order.amount_cents!==session.amount_total)return {ok:false as const,status:422,error:"Ticket order verification failed."};if(session.payment_status!=="paid")return {ok:true as const,pending:true,idempotent:false};const paymentIntent=typeof session.payment_intent==="string"?session.payment_intent:session.payment_intent?.id??null;const {data,error}=await db.rpc("fulfill_ticket_order",{p_stripe_session_id:session.id,p_payment_intent_id:paymentIntent});if(error)return {ok:false as const,status:500,error:error.message};return {ok:true as const,pending:false,idempotent:Boolean((data as any)?.idempotent)};}
