import "server-only";

import { getSupabaseAdmin } from "@/lib/supabase/server";

export type ChurchTaxProfileRow = {
  id: string;
  church_id: string;
  legal_name: string;
  ein: string;
  verification_status: string;
  certificate_bucket: string;
  certificate_object_path: string | null;
  certificate_content_type: string | null;
  certificate_byte_size: number | null;
  certificate_sha256: string | null;
  uploaded_by: string | null;
  uploaded_at: string | null;
  reviewed_by: string | null;
  reviewed_at: string | null;
  rejection_reason: string | null;
  expires_on: string | null;
  owner_notes: string | null;
  created_at: string;
  updated_at: string;
};

export type TaxExemptReviewAction = "verify" | "reject";

export type PendingReviewTaxProfileRow = ChurchTaxProfileRow & {
  church_name: string | null;
};

export async function getChurchTaxProfileById(
  profileId: string,
): Promise<ChurchTaxProfileRow | null> {
  const { data, error } = await getSupabaseAdmin()
    .from("church_tax_profiles")
    .select("*")
    .eq("id", profileId)
    .maybeSingle();

  if (error) {
    throw error;
  }

  return (data as ChurchTaxProfileRow | null) ?? null;
}

/**
 * Platform-owner queue: profiles awaiting certificate audit.
 */
export async function listPendingReviewTaxProfiles(
  limit = 100,
): Promise<PendingReviewTaxProfileRow[]> {
  const safeLimit = Number.isFinite(limit)
    ? Math.min(Math.max(Math.floor(limit), 1), 200)
    : 100;

  const { data, error } = await getSupabaseAdmin()
    .from("church_tax_profiles")
    .select(
      "*, church_organizations ( id, name )",
    )
    .eq("verification_status", "pending_review")
    .order("uploaded_at", { ascending: true, nullsFirst: false })
    .limit(safeLimit);

  if (error) {
    throw error;
  }

  return (data ?? []).map((row) => {
    const source = row as ChurchTaxProfileRow & {
      church_organizations?:
        | { id: string; name: string | null }
        | { id: string; name: string | null }[]
        | null;
    };
    const org = Array.isArray(source.church_organizations)
      ? source.church_organizations[0]
      : source.church_organizations;
    const { church_organizations: _omit, ...profile } = source;
    return {
      ...(profile as ChurchTaxProfileRow),
      church_name: org?.name?.trim() || null,
    };
  });
}

/**
 * Platform-owner mutator for tax-exempt review.
 * Schema stamps reviewer identity on reviewed_by / reviewed_at
 * (there is no verified_by / verified_at column in church_tax_profiles).
 */
export async function reviewChurchTaxProfile(input: {
  profileId: string;
  action: TaxExemptReviewAction;
  reviewerUserId: string;
  internalNotes: string | null;
}): Promise<ChurchTaxProfileRow> {
  const existing = await getChurchTaxProfileById(input.profileId);
  if (!existing) {
    throw Object.assign(new Error("Tax-exempt profile not found."), {
      status: 404,
    });
  }

  if (!existing.certificate_object_path) {
    throw Object.assign(
      new Error("Cannot review a profile that has no uploaded certificate object."),
      { status: 409 },
    );
  }

  if (
    existing.verification_status !== "pending_review" &&
    existing.verification_status !== "pending_upload"
  ) {
    throw Object.assign(
      new Error(
        `Profile cannot be reviewed from status '${existing.verification_status}'.`,
      ),
      { status: 409 },
    );
  }

  const reviewedAt = new Date().toISOString();
  const notes =
    typeof input.internalNotes === "string" && input.internalNotes.trim()
      ? input.internalNotes.trim().slice(0, 2000)
      : null;

  if (input.action === "verify") {
    const { data, error } = await getSupabaseAdmin()
      .from("church_tax_profiles")
      .update({
        verification_status: "verified",
        reviewed_by: input.reviewerUserId,
        reviewed_at: reviewedAt,
        rejection_reason: null,
        owner_notes: notes,
      })
      .eq("id", input.profileId)
      .select("*")
      .single();

    if (error || !data) {
      throw error ?? new Error("Unable to verify tax-exempt profile.");
    }
    return data as ChurchTaxProfileRow;
  }

  if (!notes || notes.length < 3) {
    throw Object.assign(
      new Error("internalNotes (min 3 characters) is required when rejecting."),
      { status: 400 },
    );
  }

  const { data, error } = await getSupabaseAdmin()
    .from("church_tax_profiles")
    .update({
      verification_status: "rejected",
      reviewed_by: input.reviewerUserId,
      reviewed_at: reviewedAt,
      rejection_reason: notes,
      owner_notes: notes,
    })
    .eq("id", input.profileId)
    .select("*")
    .single();

  if (error || !data) {
    throw error ?? new Error("Unable to reject tax-exempt profile.");
  }

  return data as ChurchTaxProfileRow;
}

import "server-only";
import { getSupabaseAdmin } from "@/lib/supabase/server";
import { TRAVEL_PROGRAM_KEY } from "@/lib/travel/types";

export type OwnerBookingTransactionRow = {
  id: string;
  user_id: string;
  lane: string;
  kind: string;
  status: string;
  provider_key: string | null;
  marketplace_attempt_id: string | null;
  offer_id: string | null;
  payment_intent_id: string | null;
  supplier_confirmation_number: string | null;
  total_amount_cents: number | null;
  tax_amount_cents: number | null;
  currency: string;
  destination_label: string | null;
  origin_label: string | null;
  start_at: string | null;
  end_at: string | null;
  failure_reason: string | null;
  started_at: string;
  updated_at: string;
  confirmed_at: string | null;
  refunded_at: string | null;
};

export async function listOwnerBookingTransactions(filters: {
  q?: string;
  userId?: string;
  provider?: string;
  kind?: string;
  status?: string;
  dateFrom?: string;
  dateTo?: string;
  amountMinCents?: number | null;
  amountMaxCents?: number | null;
  sort?: string;
}): Promise<OwnerBookingTransactionRow[]> {
  const db = getSupabaseAdmin();
  const sort = filters.sort || "started_at_desc";
  const ascending = sort.endsWith("_asc");
  const sortColumn =
    sort.startsWith("updated_at")
      ? "updated_at"
      : sort.startsWith("amount")
        ? "total_amount_cents"
        : "started_at";

  let query = db
    .from("travel_booking_transactions")
    .select(
      "id,user_id,lane,kind,status,provider_key,marketplace_attempt_id,offer_id,payment_intent_id,supplier_confirmation_number,total_amount_cents,tax_amount_cents,currency,destination_label,origin_label,start_at,end_at,failure_reason,started_at,updated_at,confirmed_at,refunded_at",
    )
    .eq("program_key", TRAVEL_PROGRAM_KEY)
    .order(sortColumn, { ascending })
    .limit(200);

  if (filters.userId) query = query.eq("user_id", filters.userId);
  if (filters.provider) query = query.eq("provider_key", filters.provider);
  if (filters.kind) query = query.eq("kind", filters.kind);
  if (filters.status) query = query.eq("status", filters.status);
  if (filters.dateFrom) query = query.gte("started_at", `${filters.dateFrom}T00:00:00.000Z`);
  if (filters.dateTo) query = query.lte("started_at", `${filters.dateTo}T23:59:59.999Z`);
  if (filters.amountMinCents != null && Number.isFinite(filters.amountMinCents)) {
    query = query.gte("total_amount_cents", Math.round(filters.amountMinCents));
  }
  if (filters.amountMaxCents != null && Number.isFinite(filters.amountMaxCents)) {
    query = query.lte("total_amount_cents", Math.round(filters.amountMaxCents));
  }

  const { data, error } = await query;
  if (error) throw new Error(error.message);
  let rows = (data ?? []) as OwnerBookingTransactionRow[];

  const q = filters.q?.trim().toLowerCase();
  if (!q) return rows;
  return rows.filter((row) => {
    const hay = [
      row.id,
      row.user_id,
      row.lane,
      row.kind,
      row.status,
      row.provider_key,
      row.marketplace_attempt_id,
      row.offer_id,
      row.payment_intent_id,
      row.supplier_confirmation_number,
      row.destination_label,
      row.origin_label,
      row.failure_reason,
    ]
      .filter(Boolean)
      .join(" ")
      .toLowerCase();
    return hay.includes(q);
  });
}

export async function listRecentTransactionEvents(transactionIds: string[], limit = 40) {
  if (!transactionIds.length) return [];
  const db = getSupabaseAdmin();
  const { data, error } = await db
