"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { fetchLiveAccessEvaluation } from "@/lib/access";
import { LIVE_STREAM_STATE_BROADCAST_EVENT } from "@/lib/live/types";
import {
  acquirePlatformChannel,
  commitPlatformChannelSubscribe,
  registerPlatformListener,
  releasePlatformChannel,
  unregisterPlatformListener,
} from "@/lib/live/platform-channel";
import { getSupabase } from "@/lib/supabase/client";

const STREAM_STATE_LISTENER_ID = "live-stream-state-broadcast";

type UseLiveStreamStateOptions = {
  /** When false, skips network/realtime sync until lifecycle allows live routing. */
  enabled?: boolean;
};

type UseLiveStreamStateResult = {
  isLive: boolean;
  isLoading: boolean;
  error: string | null;
};

export function useLiveStreamState(
  options: UseLiveStreamStateOptions = {},
): UseLiveStreamStateResult {
  const { enabled = true } = options;
  const [isLive, setIsLive] = useState(false);
  const [isLoading, setIsLoading] = useState(enabled);
  const [error, setError] = useState<string | null>(null);
  const syncRef = useRef<() => Promise<void>>(async () => {});

  const syncFromAccessApi = useCallback(async () => {
    if (!enabled) return;

    try {
      const evaluation = await fetchLiveAccessEvaluation();
      setIsLive(evaluation.streamIsLive);
      setError(null);
    } catch (syncError) {
      console.error("Live stream state sync failed:", syncError);
      setError("Unable to load live stream status.");
    } finally {
      setIsLoading(false);
    }
  }, [enabled]);

  syncRef.current = syncFromAccessApi;

  useEffect(() => {
    if (!enabled) {
      setIsLoading(false);
      return;
    }

    setIsLoading(true);

    let cancelled = false;
    let supabase: ReturnType<typeof getSupabase>;

    try {
      supabase = getSupabase();
    } catch (initError) {
      console.error("Live stream state init failed:", initError);
      queueMicrotask(() => {
        if (!cancelled) {
          setError("Live stream state is unavailable.");
          setIsLoading(false);
        }
      });
      return;
    }

    queueMicrotask(() => {
      if (!cancelled) {
        void syncFromAccessApi();
      }
    });

    acquirePlatformChannel(supabase);

    registerPlatformListener(STREAM_STATE_LISTENER_ID, (channel) =>
      channel.on("broadcast", { event: LIVE_STREAM_STATE_BROADCAST_EVENT }, () => {
        if (cancelled) return;
        void syncRef.current();
      }),
    );

    commitPlatformChannelSubscribe();

    return () => {
      cancelled = true;
      unregisterPlatformListener(STREAM_STATE_LISTENER_ID);
      releasePlatformChannel(supabase);
    };
  }, [enabled, syncFromAccessApi]);

  return {
    isLive,
    isLoading: enabled ? isLoading : false,
    error: enabled ? error : null,
  };
}

/* COGIC LIVE — production service worker (Web Push + notification click). */
/* eslint-disable no-restricted-globals */

self.addEventListener("install", (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

function safePath(url) {
  if (typeof url !== "string" || !url.startsWith("/")) return "/updates";
  if (url.startsWith("//") || url.includes("://") || url.includes("..")) return "/updates";
  const allowedExact = ["/live", "/updates", "/program", "/replays", "/my-convocation"];
  if (allowedExact.includes(url)) return url;
  if (url.startsWith("/replays/") && url.length < 120) return url;
  return "/updates";
}

self.addEventListener("push", (event) => {
  let payload = {
    title: "COGIC LIVE",
    body: "You have a new update.",
    url: "/updates",
    tag: "cogic-live",
  };

  try {
    if (event.data) {
      const data = event.data.json();
      payload = {
        title: typeof data.title === "string" ? data.title : payload.title,
        body: typeof data.body === "string" ? data.body : payload.body,
        url: safePath(typeof data.url === "string" ? data.url : payload.url),
        tag: typeof data.tag === "string" ? data.tag : payload.tag,
      };
    }
  } catch {
    try {
      const text = event.data ? event.data.text() : "";
      if (text) payload.body = text.slice(0, 180);
    } catch {
      // keep defaults
    }
  }

  event.waitUntil(
    self.registration.showNotification(payload.title, {
      body: payload.body,
      icon: "/branding/cogic-seal.png",
      badge: "/branding/cogic-seal.png",
      tag: payload.tag,
      data: { url: payload.url },
      renotify: true,
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = safePath(event.notification?.data?.url || "/updates");

  event.waitUntil(
    (async () => {
      const allClients = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });
      for (const client of allClients) {
        if ("focus" in client) {
          await client.focus();
          if ("navigate" in client) {
            await client.navigate(target);
            return;
          }
        }
      }
      if (self.clients.openWindow) {
        await self.clients.openWindow(target);
      }
    })(),
  );
});
